from pathlib import Path

reducer_path = Path("tools/research_runtime_reducer.py")
text = reducer_path.read_text(encoding="utf-8")

old_handoff = '''        if kind == "HANDOFF":\n            next_action = event.get("next_action")\n            if not isinstance(next_action, str) or not next_action.strip():\n                ignore(state, index, "HANDOFF requires next_action")\n                continue\n            state["state"] = "HANDOFF_READY"\n            if event.get("progress_ref"):\n                state["last_progress_ref"] = event["progress_ref"]\n            state["last_progress_at"] = event["at"]\n            state["next_action"] = next_action\n            state["claim_id"] = None\n            state["actor"] = None\n            release_claim_identity(state)\n            state["lease_until"] = None\n            continue\n'''

new_handoff = '''        if kind == "HANDOFF":\n            next_action = event.get("next_action")\n            if not isinstance(next_action, str) or not next_action.strip():\n                ignore(state, index, "HANDOFF requires next_action")\n                continue\n            result_id = event.get("result_id")\n            if result_id is not None and (not isinstance(result_id, str) or not result_id.strip()):\n                ignore(state, index, "HANDOFF result_id must be a nonempty string when supplied")\n                continue\n            # A result-bearing HANDOFF is a provisional review barrier even before\n            # the immutable result record lands on main.  Plain HANDOFF remains a\n            # researcher-to-researcher continuation surface.\n            state["state"] = "FROZEN_RETURN" if result_id is not None else "HANDOFF_READY"\n            if isinstance(result_id, str):\n                state["result_id"] = result_id.strip()\n            else:\n                state.pop("result_id", None)\n            if event.get("progress_ref"):\n                state["last_progress_ref"] = event["progress_ref"]\n            state["last_progress_at"] = event["at"]\n            state["next_action"] = next_action\n            state["claim_id"] = None\n            state["actor"] = None\n            release_claim_identity(state)\n            state["lease_until"] = None\n            continue\n'''

if text.count(old_handoff) != 1:
    raise SystemExit(f"expected exactly one HANDOFF reducer block, found {text.count(old_handoff)}")
text = text.replace(old_handoff, new_handoff)

old_dispatch = '''    if state["state"] in {"DONE", "SUPERSEDED"}:\n        state["dispatch_state"] = "COMPLETE"\n    elif state["state"] == "BLOCKED" and complete_hard_block(state.get("hard_block")):\n        state["dispatch_state"] = "BLOCKED"\n    elif state.get("claim_id"):\n        state["dispatch_state"] = "LEASED"\n    elif state["state"] in {"READY", "HANDOFF_READY"}:\n        state["dispatch_state"] = "NEEDS_DISPATCH"\n    else:\n        state["dispatch_state"] = "DORMANT"\n'''

new_dispatch = '''    if state["state"] in {"DONE", "SUPERSEDED"}:\n        state["dispatch_state"] = "COMPLETE"\n    elif state["state"] == "BLOCKED" and complete_hard_block(state.get("hard_block")):\n        state["dispatch_state"] = "BLOCKED"\n    elif state["state"] == "FROZEN_RETURN":\n        state["dispatch_state"] = "AWAITING_REVIEW"\n    elif state.get("claim_id"):\n        state["dispatch_state"] = "LEASED"\n    elif state["state"] in {"READY", "HANDOFF_READY"}:\n        state["dispatch_state"] = "NEEDS_DISPATCH"\n    else:\n        state["dispatch_state"] = "DORMANT"\n'''

if text.count(old_dispatch) != 1:
    raise SystemExit(f"expected exactly one final dispatch block, found {text.count(old_dispatch)}")
text = text.replace(old_dispatch, new_dispatch)
reducer_path.write_text(text, encoding="utf-8")

Path("tests/test_result_handoff_dispatch_guard.py").write_text('''import unittest\n\nfrom tools import research_runtime_reducer as rr\n\n\ndef task():\n    return {\n        "task_id": "RS-T1",\n        "base_state": "READY",\n        "priority": "P0",\n        "leverage": "HIGH",\n        "kind": "RESEARCH",\n        "last_progress_at": "2026-09-01T00:00:00+00:00",\n        "next_action": "continue",\n    }\n\n\ndef event(kind, at, claim_id="c1", **extra):\n    value = {\n        "schema": rr.EVENT_SCHEMA,\n        "event": kind,\n        "task_id": "RS-T1",\n        "claim_id": claim_id,\n        "at": at,\n    }\n    value.update(extra)\n    return value\n\n\nclass ResultHandoffDispatchGuardTests(unittest.TestCase):\n    def reduce(self, handoff_extra):\n        rid = rr.researcher_id_for_claim(task(), "c1")\n        return rr.reduce_task(\n            task(),\n            [\n                event("CLAIM", "2026-09-01T00:00:00+00:00", lease_minutes=30),\n                event(\n                    "HANDOFF",\n                    "2026-09-01T00:10:00+00:00",\n                    researcher_id=rid,\n                    next_action="Driver review exact frozen result",\n                    **handoff_extra,\n                ),\n            ],\n            default_lease_minutes=30,\n            now=rr.parse_time("2026-09-01T00:11:00+00:00"),\n        )\n\n    def test_result_bearing_handoff_waits_for_review(self):\n        state = self.reduce({"result_id": "RR-TEST-123"})\n        self.assertEqual("FROZEN_RETURN", state["state"])\n        self.assertEqual("AWAITING_REVIEW", state["dispatch_state"])\n        self.assertEqual("RR-TEST-123", state["result_id"])\n        self.assertIsNone(state["claim_id"])\n\n    def test_result_bearing_handoff_is_not_a_fresh_candidate(self):\n        state = self.reduce({"result_id": "RR-TEST-123"})\n        state.update({"kind": "RESEARCH", "priority": "P0", "leverage": "HIGH"})\n        self.assertIsNone(rr.select_state([state], rr.load_policy(), kind="RESEARCH"))\n\n    def test_plain_handoff_remains_dispatchable(self):\n        state = self.reduce({})\n        self.assertEqual("HANDOFF_READY", state["state"])\n        self.assertEqual("NEEDS_DISPATCH", state["dispatch_state"])\n        self.assertNotIn("result_id", state)\n\n    def test_malformed_result_id_does_not_open_fresh_dispatch(self):\n        state = self.reduce({"result_id": "   "})\n        self.assertEqual("CLAIMED", state["state"])\n        self.assertEqual("LEASED", state["dispatch_state"])\n        self.assertEqual("c1", state["claim_id"])\n        self.assertTrue(any("result_id" in item["reason"] for item in state["ignored_events"]))\n\n\nif __name__ == "__main__":\n    unittest.main()\n''', encoding="utf-8")
